edits.after:
if (*cow_len == 0) {
	/*
	 * We should find a refcounted record in the
	 * first pass. If not, something is wrong with
	 * the extent tree.
	 */
	if (!(rec->e_flags & OCFS2_EXT_REFCOUNTED)) {
		ret = ocfs2_error(inode->i_sb,
			"Inode %lu has non refcounted record in index %d\n",
			inode->i_ino, i);
		goto out;
	}
	*cow_start = le32_to_cpu(rec->e_cpos);
}

edits.before:
if (*cow_len == 0) {
	/*
	 * We should find a refcounted record in the
	 * first pass.
	 */
	BUG_ON(!(rec->e_flags & OCFS2_EXT_REFCOUNTED));
	*cow_start = le32_to_cpu(rec->e_cpos);
}
